      return Mq('categories', 'People were asked which of four things scared them most.' + T(['Fear', 'Number of people'], cats.map(function (c, i) { return [c, fr[i]]; })) + 'Which is the modal category?', best, cats.filter(function (c) { return c !== best; }), 'The mode can be used for categories. "' + best + '" was chosen by the most people (' + mx(fr) + '), so it is the mode. You cannot work out a mean or median for categories like these.');
